mapper.sql:
WHERE (t.tenant_type='CLIENT' OR t.tenant_id IS NULL)
AND t.owner_ref_id=#{filter.clientId}
AND t.tenant_name LIKE #{filter.clientName} ESCAPE '!'
AND c.credential_id=#{filter.credentialId}
AND c.key_prefix=#{filter.keyPrefix} AND BINARY c.key_prefix=BINARY #{filter.keyPrefix}


        AND c.status='REVOKED'
        AND c.status!='REVOKED' AND (c.status='EXPIRED' OR c.expires_time<=#{asOf})
        AND c.status='ACTIVE' AND c.expires_time>#{asOf}



    AND EXISTS(SELECT 1 FROM t_api_credential_scope g WHERE g.credential_id=c.credential_id
        AND g.scope_code=#{filter.scopeCode} AND BINARY g.scope_code=BINARY #{filter.scopeCode})
